"""Render results/RESULTS.md from results/<arm>/eval/{summary.json,auc_grid.csv} for every arm that has run."""
import glob, json, os, pandas as pd
out = ["# Results\n", "Auto-generated by `python scripts/make_results.py`. Headline metric: ROC AUC. Class ratio real:fake ≈ 1:1.77; majority-class accuracy ≈ 0.64.\n"]
for sp in sorted(glob.glob("results/*/eval/summary.json")):
    s = json.load(open(sp)); arm = os.path.dirname(os.path.dirname(sp))
    df = pd.read_csv(os.path.join(arm, "eval", "auc_grid.csv")).fillna("")
    out.append(f"\n## {s['config']}  \n`{s['backbone']}` — {s['backbone_params_B']:.3f} B params\n")
    out.append(f"| | AUC | error (1-AUC) |\n|---|---|---|")
    out.append(f"| clean, **full** designated val set (n={s['n_full_set']}) | **{s['clean_auc_full_set']:.4f}** | {1-s['clean_auc_full_set']:.4f} |")
    out.append(f"| clean, full set **deduplicated** (n={s['n_full_set_dedup']}: {s['n_real_dedup']} real / {s['n_fake_dedup']} fake) | {s['clean_auc_full_set_dedup']:.4f} | {1-s['clean_auc_full_set_dedup']:.4f} |")
    out.append(f"| clean, eval subset, fakes vs COCO reals | {s['clean_auc']:.4f} | {1-s['clean_auc']:.4f} |")
    out.append(f"| clean, eval subset, fakes vs **ImageNet (alt) reals** | {s['clean_auc_alt_real']:.4f} | {1-s['clean_auc_alt_real']:.4f} |")
    out.append(f"| worst single transform: `{s['worst_transform']}` | {s['worst_auc']:.4f} (alt real {s['worst_auc_alt_real']:.4f}) | {1-s['worst_auc']:.4f} |")
    out.append(f"\n**Shortcut gap (COCO-real AUC − alt-real AUC, clean): {s['shortcut_gap_clean']:+.4f}**  · max degradation delta: {s['max_delta']:.4f}  · mean degraded AUC: {s['mean_degraded_auc']:.4f}\n")
    out.append(f"Accuracy@0.5 on full set: {s['full_set_acc@0.5']:.4f}, balanced accuracy {s['full_set_bal_acc@0.5']:.4f} (majority baseline {s['majority_class_baseline_acc']:.4f}).\n")
    out.append("\n### Per-transform grid (eval subset)\n")
    cols = ["transform", "level", "auc_coco_real", "delta_coco", "err_coco_real", "auc_alt_real", "shortcut_gap", "bal_acc@0.5"]
    out.append(df[cols].to_markdown(index=False, floatfmt=".4f"))
    out.append(f"\n![grid]({os.path.relpath(os.path.join(arm,'eval','auc_grid.png'),'results')})\n")
    abl = os.path.join(arm, "eval", "auc_grid_sid_only_ablation.csv")
    if os.path.exists(abl):
        out.append("\n### Data ablation: head trained on SID_Set only (WildFake train slice removed)\n")
        out.append("Same cached features, same linear-head recipe; only the training data changes. See README §limitations for the WildFake format confound this isolates.\n")
        out.append(pd.read_csv(abl).fillna("").to_markdown(index=False, floatfmt=".4f"))
    out.append("\n### Operating points (clean)\n")
    out.append(pd.DataFrame(s["thresholds"]).fillna("").to_markdown(index=False, floatfmt=".4f"))
    out.append(f"\nROC: `{arm}/eval/roc.png` · FPR vs threshold: `{arm}/eval/fpr_vs_threshold.png` · error contact sheets: `{arm}/eval/errors_fp.png`, `errors_fn.png`\n")
if os.path.exists("results/comparison.csv"):
    out.append("\n## Baseline comparison\n"); out.append(pd.read_csv("results/comparison.csv").to_markdown(index=False, floatfmt=".4f"))
open("results/RESULTS.md", "w").write("\n".join(out) + "\n"); print("wrote results/RESULTS.md")
